package proxy

import (
	"encoding/hex"
	"testing"
)

// Real ClientHello records sent by the Chromium of the harness images (Playwright's chromium 1247), captured by
// a plain TCP listener that Chromium was pointed at with --host-resolver-rules, several per site because every
// hello has its own random GREASE values, extension order and padding. They pin that the parser, with its rule
// against a repeated extension, never refuses what a real browser sends, and that it sees the ECH extension
// Chromium always includes.
var chromiumHellos = []struct {
	name   string
	record string
}{
	{"alpha.example.test", ""},
	{"alpha.example.test", ""},
	{"alpha.example.test", ""},
	{"alpha.example.test", ""},
	{"beta-longer-name.example.org", ""},
	{"beta-longer-name.example.org", ""},
	{"beta-longer-name.example.org", ""},
	{"beta-longer-name.example.org", ""},
	{"c.example.net", ""},
	{"c.example.net", ""},
	{"c.example.net", ""},
	{"c.example.net", ""},
}

func TestTheParserAcceptsRealChromiumClientHellos(t *testing.T) {
	for _, c := range chromiumHellos {
		record, err := hex.DecodeString(c.record)
		if err != nil {
			t.Fatal(err)
		}
		if record[0] != recordTypeHandshake {
			t.Fatalf("%s: not a handshake record", c.name)
		}
		name, ech, err := parseServerName(record[5:])
		if err != nil || name != c.name || !ech {
			t.Errorf("%s: parseServerName = %q, ech %v, %v", c.name, name, ech, err)
		}
	}
}
